#!/bin/sh
set -eu

# Vault and this bootstrap container start concurrently under Compose — dev
# mode auto-unseals almost instantly, but there's no guarantee it's ready
# before this script's first command runs. A short retry loop avoids racing
# the network instead of guessing a fixed sleep duration.
until vault status >/dev/null 2>&1; do
  echo "waiting for vault..."
  sleep 1
done

# Decision: check for an existing secret before writing, rather than
# always overwriting. Because: in production this script receives a fresh
# random DB_PASSWORD generated by Ansible on every deploy run (nothing
# persists it outside Vault) — but Postgres only reads its password file
# once, when its data directory is first initialized. Overwriting an
# already-adopted password here would leave Vault holding a value
# Postgres was never actually given. This guard is what makes it safe to
# hand this script a brand new random candidate on every single run.
if vault kv get secret/bggg/db >/dev/null 2>&1; then
  echo "bootstrap skipped: secret/bggg/db already exists"
  exit 0
fi

# KV v2 is mounted at 'secret/' by default in dev mode. This is the same
# engine and path that infra/vault/agent.hcl reads from via
# 'secret/data/bggg/db' — the '/data/' segment is KV v2's own convention,
# not something we chose; the CLI hides it, the HTTP API (which templates
# use) does not.
vault kv put secret/bggg/db password="$DB_PASSWORD"

echo "bootstrap complete: secret/bggg/db written"
